36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.rest.validation.CustomerCodeGenerator;
39	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
40	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
41	import org.springframework.samples.petclinic.rest.validation.OwnerHouseholdRegistrar;
42	import org.springframework.samples.petclinic.rest.validation.OwnerHouseholdUniquenessValidator;
43	import org.springframework.samples.petclinic.rest.validation.OwnerTelephoneUniquenessValidator;
44	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    private final ClinicService clinicService;
64	
65	    private final OwnerMapper ownerMapper;
66	
67	    private final PetMapper petMapper;
68	
69	    private final VisitMapper visitMapper;
70	
71	    private final OwnerTelephoneUniquenessValidator telephoneUniquenessValidator;
72	
73	    private final OwnerHouseholdUniquenessValidator householdUniquenessValidator;
74	
75	    private final OwnerHouseholdRegistrar householdRegistrar;
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper,
81	                                 OwnerTelephoneUniquenessValidator telephoneUniquenessValidator,
82	                                 OwnerHouseholdUniquenessValidator householdUniquenessValidator,
83	                                 OwnerHouseholdRegistrar householdRegistrar) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	        this.telephoneUniquenessValidator = telephoneUniquenessValidator;
89	        this.householdUniquenessValidator = householdUniquenessValidator;
90	        this.householdRegistrar = householdRegistrar;
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
96	        Collection<Owner> owners;
97	        if (lastName != null) {
98	            owners = this.clinicService.findOwnerByLastName(lastName);
99	        } else {
100	            owners = this.clinicService.findAllOwners();
101	        }
102	        if (owners.isEmpty()) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
111	        Owner owner = this.clinicService.findOwnerById(ownerId);
112	        if (owner == null) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        OwnerFieldsValidator.validateRequiredFields(ownerFieldsDto);
122	        HttpHeaders headers = new HttpHeaders();
123	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
124	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
125	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
126	        this.telephoneUniquenessValidator.validateUnique(owner.getTelephone());
127	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
128	            this.householdUniquenessValidator.validateUnique(owner.getLastName(), owner.getAddress());
129	        } else {
130	            this.householdRegistrar.assignHousehold(owner);
131	        }
132	        owner.setCustomerCode(CustomerCodeGenerator.generate(owner.getLastName(), this.clinicService.countOwners()));
